//! C13b source-authored expectations frozen before implementation or runtime.
use ktlsp_parser::{FileKind, Parsed, Parser, ParserError, SourceSnapshot};
use serde_json::{Value, json};
use std::sync::atomic::AtomicBool;

fn declaration(kind: &str) -> bool {
    matches!(
        kind,
        "CLASS" | "OBJECT_DECLARATION" | "FUN" | "PROPERTY" | "TYPEALIAS"
    )
}

fn projection(tree: &Parsed) -> Value {
    let elements = tree.elements();
    Value::Array(
        elements
            .iter()
            .filter(|e| {
                !e.token
                    && (declaration(&e.kind)
                        || matches!(
                            e.kind.as_str(),
                            "TYPE_PARAMETER_LIST"
                                | "TYPE_PARAMETER"
                                | "TYPE_REFERENCE"
                                | "USER_TYPE"
                                | "DYNAMIC_TYPE"
                                | "REFERENCE_EXPRESSION"
                                | "VALUE_PARAMETER_LIST"
                                | "VALUE_PARAMETER"
                                | "TYPE_ARGUMENT_LIST"
                                | "TYPE_PROJECTION"
                                | "ANNOTATION_ENTRY"
                                | "PROPERTY_ACCESSOR"
                        ))
            })
            .map(|e| {
                let mut parent = e.parent;
                let owner = loop {
                    match parent {
                        Some(id) if declaration(&elements[id].kind) => {
                            break Some((elements[id].start, elements[id].end));
                        }
                        Some(id) => parent = elements[id].parent,
                        None => break None,
                    }
                };
                json!([
                    e.kind,
                    e.start,
                    e.end,
                    elements[e.parent.unwrap()].kind,
                    owner
                ])
            })
            .collect(),
    )
}

fn names(tree: &Parsed) -> Value {
    let elements = tree.elements();
    Value::Array(
        elements
            .iter()
            .filter(|e| {
                e.token
                    && e.kind == "IDENTIFIER"
                    && e.parent.is_some_and(|p| declaration(&elements[p].kind))
            })
            .map(|e| {
                json!([
                    elements[e.parent.unwrap()].start,
                    e.start,
                    e.end,
                    &tree.source()[e.start..e.end]
                ])
            })
            .collect(),
    )
}

fn diagnostics(tree: &Parsed) -> Value {
    Value::Array(
        tree.diagnostics()
            .iter()
            .map(|d| json!([d.start, d.end, d.message]))
            .collect(),
    )
}

fn token(tree: &Parsed, expected: &Value, default_kind: &str) {
    if expected.is_null() {
        return;
    }
    let a = expected[0].as_u64().unwrap() as usize;
    let b = expected[1].as_u64().unwrap() as usize;
    let spelling = expected[2].as_str().unwrap();
    let parent = expected[3].as_str().unwrap();
    let kind = if default_kind == "DOT" {
        spelling
    } else {
        default_kind
    };
    assert!(tree.elements().iter().any(|e| e.token
        && e.kind == kind
        && (e.start, e.end) == (a, b)
        && e.parent.is_some_and(|p| tree.elements()[p].kind == parent)
        && (default_kind == "DOT" || &tree.source()[a..b] == spelling)));
}

fn compatibility(tree: &Parsed, case: &Value) {
    let id = case["id"].as_str().unwrap();
    let source = tree.source();
    let elements = tree.elements();
    let class = || {
        elements
            .iter()
            .find(|e| !e.token && e.kind == "CLASS")
            .unwrap()
    };
    if id == "decline-header-8" {
        // This recorded exclusion is superseded by the finite qualified-receiver contract.
        assert_eq!(
            projection(tree),
            json!([
                ["CLASS", 0, 11, "KT_FILE", null],
                ["TYPE_PARAMETER_LIST", 9, 11, "CLASS", [0, 11]],
                ["TYPE_PARAMETER", 10, 11, "TYPE_PARAMETER_LIST", [0, 11]],
                ["FUN", 12, 40, "KT_FILE", null],
                ["TYPE_REFERENCE", 16, 26, "FUN", [12, 40]],
                ["USER_TYPE", 16, 26, "TYPE_REFERENCE", [12, 40]],
                ["USER_TYPE", 16, 19, "USER_TYPE", [12, 40]],
                ["REFERENCE_EXPRESSION", 16, 19, "USER_TYPE", [12, 40]],
                ["REFERENCE_EXPRESSION", 20, 26, "USER_TYPE", [12, 40]],
                ["VALUE_PARAMETER_LIST", 34, 36, "FUN", [12, 40]]
            ]),
            "{id}"
        );
        assert_eq!(
            names(tree),
            json!([[0, 6, 9, "Box"], [12, 27, 34, "healthy"]]),
            "{id}"
        );
        assert_eq!(diagnostics(tree), json!([[11, 11, "Missing '>'"]]), "{id}");
    } else if id == "decline-header-10" {
        // The finite nullable-receiver contract supersedes only this recorded exclusion.
        assert_eq!(
            projection(tree),
            json!([
                ["CLASS", 0, 11, "KT_FILE", null],
                ["TYPE_PARAMETER_LIST", 9, 11, "CLASS", [0, 11]],
                ["TYPE_PARAMETER", 10, 11, "TYPE_PARAMETER_LIST", [0, 11]],
                ["FUN", 12, 37, "KT_FILE", null],
                ["TYPE_REFERENCE", 16, 23, "FUN", [12, 37]],
                ["USER_TYPE", 16, 22, "NULLABLE_TYPE", [12, 37]],
                ["REFERENCE_EXPRESSION", 16, 22, "USER_TYPE", [12, 37]],
                ["VALUE_PARAMETER_LIST", 31, 33, "FUN", [12, 37]]
            ]),
            "{id}"
        );
        assert_eq!(
            names(tree),
            json!([[0, 6, 9, "Box"], [12, 24, 31, "healthy"]]),
            "{id}"
        );
        assert_eq!(diagnostics(tree), json!([[11, 11, "Missing '>'"]]), "{id}");
        let nullable = elements
            .iter()
            .find(|e| !e.token && e.kind == "NULLABLE_TYPE" && (e.start, e.end) == (16, 23))
            .unwrap();
        let reference = &elements[nullable.parent.unwrap()];
        assert_eq!(
            (reference.kind.as_str(), reference.start, reference.end),
            ("TYPE_REFERENCE", 16, 23)
        );
        let function = &elements[reference.parent.unwrap()];
        assert_eq!(
            (function.kind.as_str(), function.start, function.end),
            ("FUN", 12, 37)
        );
        token(
            tree,
            &json!([16, 22, "String", "REFERENCE_EXPRESSION"]),
            "IDENTIFIER",
        );
        token(tree, &json!([22, 23, "QUEST", "NULLABLE_TYPE"]), "DOT");
        token(tree, &json!([23, 24, "DOT", "FUN"]), "DOT");
    } else if id.starts_with("decline-header-") {
        assert_eq!(class().start, 0, "{id}");
        assert!(class().end > 11, "{id}");
        assert!(!tree.diagnostics().is_empty(), "{id}");
    } else if id.starts_with("incomplete-bound-") {
        let fun_start = source.find("fun String.healthy").unwrap();
        assert!(
            !elements.iter().any(|e| !e.token
                && e.kind == "FUN"
                && e.start == fun_start
                && e.end == source.len()
                && e.parent.is_some_and(|p| elements[p].kind == "KT_FILE")),
            "{id}"
        );
        assert!(!tree.diagnostics().is_empty(), "{id}");
        if source.contains("@A") {
            let (fun_id, fun) = elements
                .iter()
                .enumerate()
                .find(|(_, e)| {
                    !e.token && e.kind == "FUN" && (e.start, e.end) == (fun_start, source.len())
                })
                .unwrap();
            assert_eq!(elements[fun.parent.unwrap()].kind, "VALUE_ARGUMENT", "{id}");
            assert!(elements.iter().any(|e| e.token
                && e.kind == "IDENTIFIER"
                && e.parent == Some(fun_id)
                && (e.start, e.end) == (fun_start + 11, fun_start + 18)));
            for (kind, start) in [("CLASS", 0), ("TYPE_PARAMETER_LIST", 9)] {
                let node = elements
                    .iter()
                    .find(|e| !e.token && e.kind == kind)
                    .unwrap();
                assert_eq!((node.start, node.end), (start, source.len()), "{id}");
            }
        }
    } else if matches!(id, "raw257" | "byte4097") {
        assert!(!case["recover"].as_bool().unwrap());
        assert!(class().end > 11, "{id}");
    } else if id == "aggregate-debit-resets-next-list" {
        assert!(class().end > source.find("fun String.declined").unwrap());
        let start = source.find("fun String.healthy").unwrap();
        let fun = elements
            .iter()
            .find(|e| !e.token && e.kind == "FUN" && (e.start, e.end) == (start, source.len()))
            .unwrap();
        assert_eq!(elements[fun.parent.unwrap()].kind, "KT_FILE");
    } else if id == "lpar-present-rpar-absent" {
        assert_eq!((class().start, class().end), (0, 11));
        let list = elements
            .iter()
            .find(|e| !e.token && e.kind == "TYPE_PARAMETER_LIST")
            .unwrap();
        assert_eq!((list.start, list.end), (9, 11));
        let parameter = elements
            .iter()
            .find(|e| !e.token && e.kind == "TYPE_PARAMETER")
            .unwrap();
        assert_eq!((parameter.start, parameter.end), (10, 11));
        let fun = elements
            .iter()
            .find(|e| !e.token && e.kind == "FUN")
            .unwrap();
        assert_eq!((fun.start, fun.end), (12, source.len()));
        assert_eq!(elements[fun.parent.unwrap()].kind, "KT_FILE");
    } else {
        // Nonclass control has no classifier recovery probe; preserve its source partition.
        assert_eq!(id, "nonclass-3");
    }
}

#[test]
fn frozen_generic_extension_contract_through_production_snapshot_worker() {
    let cases: Vec<Value> = serde_json::from_str(FIXTURES).unwrap();
    assert_eq!(cases.len(), 70);
    assert_eq!(
        cases
            .iter()
            .filter(|c| c.get("projection").is_some())
            .count(),
        38
    );
    let parser = Parser::new(env!("CARGO_BIN_EXE_ktlsp-parser-worker")).unwrap();
    for case in &cases {
        let id = case["id"].as_str().unwrap();
        let source = case["source"].as_str().unwrap();
        assert_eq!(
            source.len(),
            case["bytes"].as_u64().unwrap() as usize,
            "{id}"
        );
        let snapshot = SourceSnapshot::new(id, 1, FileKind::Source, source).unwrap();
        let accepted = parser
            .parse_snapshot(&snapshot, &AtomicBool::new(false))
            .unwrap_or_else(|error| panic!("{id}: {error:?}"));
        assert_eq!(accepted.snapshot(), &snapshot);
        let tree = accepted.tree_for(&snapshot).unwrap();
        assert_eq!(tree.source(), source);
        let mut cursor = 0;
        for e in tree.elements().iter().filter(|e| e.token) {
            assert_eq!(e.start, cursor, "{id}");
            assert!(source.is_char_boundary(e.start) && source.is_char_boundary(e.end));
            cursor = e.end;
        }
        assert_eq!(cursor, source.len(), "{id}");
        if let Some(expected) = case.get("projection") {
            assert_eq!(&projection(tree), expected, "{id}");
            assert_eq!(names(tree), case["declaration_names"], "{id}");
            assert_eq!(diagnostics(tree), case["diagnostics"], "{id}");
            for field in ["receiver_token", "parameter_name"] {
                token(tree, &case[field], "IDENTIFIER");
            }
            token(tree, &case["receiver_separator"], "DOT");
            if let Some(range) = case["type_parameter_name"].as_array() {
                let start = range[0].as_u64().unwrap() as usize;
                let end = range[1].as_u64().unwrap() as usize;
                assert!(
                    tree.elements().iter().any(|e| e.token
                        && e.kind == "IDENTIFIER"
                        && (e.start, e.end) == (start, end)
                        && e.parent
                            .is_some_and(|p| tree.elements()[p].kind == "TYPE_PARAMETER")),
                    "{id}"
                );
            }
            for (offset, expected) in case["positions"].as_object().unwrap() {
                let offset = offset.parse::<usize>().unwrap();
                if expected.as_str() == Some("INVALID_CRLF_MIDPOINT") {
                    assert!(tree.position(offset).is_err(), "{id}: {offset}");
                } else {
                    let actual = tree.position(offset).unwrap();
                    assert_eq!(
                        json!([actual.line, actual.character]),
                        *expected,
                        "{id}: {offset}"
                    );
                }
            }
            if let Some(offsets) = case["invalid_utf8_offsets"].as_array() {
                for offset in offsets {
                    assert!(
                        tree.position(offset.as_u64().unwrap() as usize).is_err(),
                        "{id}"
                    );
                }
            }
        } else {
            compatibility(tree, case);
        }
        let healthy = SourceSnapshot::new(id, 2, FileKind::Source, "fun healthy() = 2").unwrap();
        assert_eq!(
            accepted.tree_for(&healthy).unwrap_err(),
            ParserError::StaleSnapshot
        );
        let followup = parser
            .parse_snapshot(&healthy, &AtomicBool::new(false))
            .unwrap();
        assert_eq!(followup.snapshot(), &healthy);
        let next = followup.tree_for(&healthy).unwrap();
        assert_eq!(next.source(), healthy.source());
        assert_eq!(
            projection(next),
            json!([
                ["FUN", 0, 17, "KT_FILE", null],
                ["VALUE_PARAMETER_LIST", 11, 13, "FUN", [0, 17]]
            ])
        );
        assert_eq!(names(next), json!([[0, 4, 11, "healthy"]]));
        assert!(next.diagnostics().is_empty());
        assert_eq!(snapshot.source(), source);
        assert_eq!(accepted.tree_for(&snapshot).unwrap().source(), source);
    }
}

